"""Independently parse files generated by the Java production serializer."""
import csv
from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
import openpyxl

base = Path(__file__).resolve().parents[1] / "core/build/test-exports"
head = ["Código", "Nome", "Confere no Kronos?"]
with (base / "coleta.csv").open(encoding="utf-8-sig", newline="") as f:
    rows = list(csv.reader(f, delimiter=";"))
assert rows[0] == head
assert len(rows) == 6 and all(len(row) == 3 for row in rows)
assert rows[1] == ["00001234567890123456789", 'Bomba d’água; setor "A"\nLinha 2', "Sim"]
assert rows[2][:2] == ["'=1+2", "'@SUM(A1)"]
assert rows[4][:2] == ["'\t -2", "' +malicioso"]
book = openpyxl.load_workbook(base / "coleta.xlsx")
sheet = book.active
assert sheet.title == "Coleta"
assert list(next(sheet.values)) == head
assert sheet.max_column == 3 and sheet.max_row == 6
assert sheet["A2"].value == "00001234567890123456789"
assert sheet["A3"].value == "=1+2" and sheet["A3"].data_type == "s"
assert sheet["B3"].value == "@SUM(A1)" and sheet["B3"].data_type == "s"
assert sheet["A4"].value == "QR-ç-😀"
assert sheet["A6"].value == "_x000A_ & < >"
assert sheet["B6"].value == "  Nome com espaços  "
assert sheet.freeze_panes == "A2"
assert sheet.auto_filter.ref == "A1:C6"
for row in sheet:
    for cell in row:
        assert cell.data_type != "f", "untrusted payload became an Excel formula"
with ZipFile(base / "coleta.xlsx") as z:
    for name in z.namelist():
        if name.endswith(".xml") or name.endswith(".rels"):
            ET.fromstring(z.read(name))
empty = openpyxl.load_workbook(base / "vazia.xlsx").active
assert list(empty.values) == [tuple(head)]
print("PASS: CSV round-trip and XLSX validated independently with Python csv, openpyxl and XML parsers")
